{
  "PROP-e5782b58-inv-013": {
    "property_id": "PROP-e5782b58-inv-013",
    "audit_result": {
      "property_id": "PROP-e5782b58-inv-013",
      "classification": "vulnerability",
      "code_path": "supabase/migrations/0000_create_member_schema.sql::RLS_policy_Allow_user_to_update_their_own_profile::L83",
      "proof_trace": "The RLS UPDATE policy on `member.members` — `USING (auth.uid() = id/supabase_auth_user_id)` — has no `WITH CHECK` clause and no column-level restriction, allowing any authenticated user to UPDATE any column in their own row, including `is_admin`. The TypeScript generated type (`types.ts:248`) confirms `is_admin?: boolean` is in the `Update` row type. The application-layer admin gate (`admin/layout.tsx:17-21`) only protects Next.js routes; it does not block direct Supabase REST API calls made with the user's own JWT.",
      "attack_scenario": "An authenticated non-admin user sends `PATCH https://<project>.supabase.co/rest/v1/members?supabase_auth_user_id=eq.<their_uuid>` with their session JWT and body `{\"is_admin\": true}`; the RLS UPDATE policy permits it because `auth.uid() = supabase_auth_user_id` is satisfied, elevating the attacker to admin and granting full access to all admin routes and data.",
      "checklist_id": "PROP-e5782b58-inv-013"
    },
    "text": "Permission_level must only be modifiable by admin users through admin user management endpoint.",
    "assertion": "forall UPDATE members.users SET is_admin: caller.is_admin == true AND via admin endpoint only",
    "covers": "SG-006",
    "severity": "CRITICAL",
    "type": "invariant"
  }
}

